'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useState, useMemo, useEffect } from 'react';
import { storage } from '@/lib/storage';
import { 
  LayoutDashboard, 
  FolderTree, 
  FileText, 
  File, 
  Image, 
  Link as LinkIcon, 
  Settings, 
  Users, 
  ShieldCheck, 
  History, 
  Database,
  UserCog,
  Building2,
  Microscope,
  TrendingUp,
  GraduationCap,
  BookOpen,
  Award,
  Download,
  Newspaper,
  Handshake,
  ChevronDown,
  ChevronRight,
  Clock,
} from 'lucide-react';

interface MenuItem {
  title: string;
  href?: string;
  icon: React.ComponentType<{ className?: string }>;
  children?: MenuItem[];
}

const menuConfig: MenuItem[] = [
  {
    title: '仪表盘',
    href: '/dashboard',
    icon: LayoutDashboard,
  },
  {
    title: '新闻动态',
    icon: Newspaper,
    children: [
      { title: '文章管理', href: '/dashboard/articles', icon: FileText },
      { title: '分类管理', href: '/dashboard/categories', icon: FolderTree },
    ],
  },
  {
    title: '学院概况',
    icon: Building2,
    children: [
      { title: '学院简介', href: '/dashboard/pages', icon: File },
      { title: '现任领导', href: '/dashboard/leaders', icon: UserCog },
      { title: '机构设置', href: '/dashboard/departments', icon: Building2 },
    ],
  },
  {
    title: '科学研究',
    icon: Microscope,
    children: [
      { title: '科研机构', href: '/dashboard/research-institutions', icon: Microscope },
      { title: '成果转化', href: '/dashboard/research-transfers', icon: TrendingUp },
    ],
  },
  {
    title: '师资队伍',
    icon: GraduationCap,
    children: [
      { title: '培养导师', href: '/dashboard/supervisors', icon: GraduationCap },
    ],
  },
  {
    title: '校企合作',
    icon: Handshake,
    children: [
      { title: '合作单位', href: '/dashboard/partners', icon: Handshake },
    ],
  },
  {
    title: '学生工作',
    icon: BookOpen,
    children: [
      { title: '学生管理', href: '/dashboard/student-documents', icon: BookOpen },
      { title: '学生风采', href: '/dashboard/student-showcases', icon: Award },
    ],
  },
  {
    title: '管理文件',
    icon: FileText,
    children: [
      { title: '政策文件', href: '/dashboard/policy-documents', icon: FileText },
      { title: '资料下载', href: '/dashboard/download-files', icon: Download },
    ],
  },
  {
    title: '网站设置',
    icon: Settings,
    children: [
      { title: 'Banner 管理', href: '/dashboard/banners', icon: Image },
      { title: '友情链接', href: '/dashboard/links', icon: LinkIcon },
      { title: '站点设置', href: '/dashboard/settings', icon: Settings },
    ],
  },
  {
    title: '系统管理',
    icon: ShieldCheck,
    children: [
      { title: '用户与角色', href: '/dashboard/users', icon: Users },
      { title: '审核中心', href: '/dashboard/review', icon: ShieldCheck },
      { title: '操作日志', href: '/dashboard/logs', icon: History },
      { title: '备份管理', href: '/dashboard/backup', icon: Database },
    ],
  },
];

/// 获取图标名称（用于存储）
const getIconName = (icon: React.ComponentType<{ className?: string }>): string => {
  return icon.name || 'FileText';
};

// 获取图标组件
const getIconComponent = (iconName: string) => {
  const iconMap: Record<string, React.ComponentType<{ className?: string }>> = {
    FileText,
    FolderTree,
    File,
    UserCog,
    Building2,
    Microscope,
    TrendingUp,
    GraduationCap,
    BookOpen,
    Award,
    Download,
    Image,
    LinkIcon,
    Settings,
    Users,
    ShieldCheck,
    History,
    Database,
    Handshake,
  };
  return iconMap[iconName] || FileText;
};

export default function Sidebar() {
  const pathname = usePathname();

  // 初始化展开状态
  const initialExpandedGroups = useMemo(() => {
    const saved = storage.getSidebarExpanded();
    if (saved.size > 0) {
      return saved;
    }

    const expanded = new Set<string>();
    menuConfig.forEach((group) => {
      if (group.children) {
        const hasActiveChild = group.children.some((child) => child.href === pathname);
        if (hasActiveChild) {
          expanded.add(group.title);
        }
      }
    });
    return expanded;
  }, [pathname]);

  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(initialExpandedGroups);
  const [recentPages, setRecentPages] = useState<Array<{ title: string; href: string; icon: string }>>([]);

  // 保存展开状态到 localStorage
  useEffect(() => {
    storage.setSidebarExpanded(expandedGroups);
  }, [expandedGroups]);

  // 加载最近访问（只在挂载时执行一次）
  useEffect(() => {
    const loadRecent = () => {
      const pages = storage.getRecentPages();
      setRecentPages(pages);
    };
    loadRecent();
     
  }, []);

  // 记录当前页面访问
  useEffect(() => {
    const updateRecent = () => {
      let currentPage: { title: string; href: string; icon: string } | null = null;

      for (const group of menuConfig) {
        if (group.href === pathname) {
          currentPage = {
            title: group.title,
            href: group.href,
            icon: getIconName(group.icon),
          };
          break;
        }
        if (group.children) {
          const child = group.children.find((c) => c.href === pathname);
          if (child) {
            currentPage = {
              title: child.title,
              href: child.href!,
              icon: getIconName(child.icon),
            };
            break;
          }
        }
      }

      if (currentPage && currentPage.href !== '/dashboard') {
        storage.addRecentPage(currentPage);
        setRecentPages(storage.getRecentPages());
      }
    };

    updateRecent();
     
  }, [pathname]);

  const toggleGroup = (title: string) => {
    setExpandedGroups((prev) => {
      const next = new Set(prev);
      if (next.has(title)) {
        next.delete(title);
      } else {
        next.add(title);
      }
      return next;
    });
  };

  const isGroupActive = (group: MenuItem) => {
    if (group.href === pathname) return true;
    if (group.children) {
      return group.children.some((child) => child.href === pathname);
    }
    return false;
  };

  const handleClearRecent = () => {
    storage.clearRecentPages();
    setRecentPages([]);
  };

  return (
    <div className="w-64 bg-white border-r border-gray-200 h-screen flex flex-col">
      {/* Logo */}
      <div className="px-6 py-8 border-b border-gray-200">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-2xl font-bold">
            吉
          </div>
          <div>
            <h1 className="font-bold text-xl text-gray-900">国卓珠海</h1>
            <p className="text-xs text-gray-500 -mt-1">后台管理系统</p>
          </div>
        </div>
      </div>

      {/* 菜单 */}
      <nav className="flex-1 px-3 py-6 overflow-y-auto">
        {/* 最近访问 */}
        {recentPages.length > 0 && (
          <div className="mb-6">
            <div className="flex items-center justify-between px-4 mb-2">
              <div className="flex items-center gap-2 text-xs font-medium text-gray-500">
                <Clock className="w-3.5 h-3.5" />
                最近访问
              </div>
              <button
                onClick={handleClearRecent}
                className="text-xs text-gray-400 hover:text-gray-600"
              >
                清空
              </button>
            </div>
            <ul className="space-y-1">
              {recentPages.map((page) => {
                const Icon = getIconComponent(page.icon);
                return (
                  <li key={page.href}>
                    <Link
                      href={page.href}
                      className={`flex items-center gap-3 px-4 py-2 rounded-xl text-sm transition-all ${
                        pathname === page.href
                          ? 'bg-blue-50 text-blue-600 font-medium'
                          : 'text-gray-600 hover:bg-gray-50'
                      }`}
                    >
                      <Icon className="w-4 h-4" />
                      {page.title}
                    </Link>
                  </li>
                );
              })}
            </ul>
            <div className="h-px bg-gray-200 my-4" />
          </div>
        )}

        {/* 主菜单 */}
        <ul className="space-y-1">
          {menuConfig.map((item) => {
            const Icon = item.icon;
            const isExpanded = expandedGroups.has(item.title);
            const isActive = isGroupActive(item);

            if (!item.children) {
              return (
                <li key={item.title}>
                  <Link
                    href={item.href!}
                    className={`flex items-center gap-3 px-4 py-3 rounded-2xl text-sm font-medium transition-all ${
                      pathname === item.href
                        ? 'bg-blue-50 text-blue-600'
                        : 'text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    <Icon className="w-5 h-5" />
                    {item.title}
                  </Link>
                </li>
              );
            }

            return (
              <li key={item.title}>
                <button
                  onClick={() => toggleGroup(item.title)}
                  className={`w-full flex items-center justify-between px-4 py-3 rounded-2xl text-sm font-medium transition-all ${
                    isActive
                      ? 'bg-blue-50 text-blue-600'
                      : 'text-gray-700 hover:bg-gray-100'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <Icon className="w-5 h-5" />
                    {item.title}
                  </div>
                  {isExpanded ? (
                    <ChevronDown className="w-4 h-4" />
                  ) : (
                    <ChevronRight className="w-4 h-4" />
                  )}
                </button>

                {isExpanded && (
                  <ul className="mt-1 ml-4 space-y-1">
                    {item.children.map((child) => {
                      const ChildIcon = child.icon;
                      const isChildActive = pathname === child.href;
                      return (
                        <li key={child.href}>
                          <Link
                            href={child.href!}
                            className={`flex items-center gap-3 px-4 py-2.5 rounded-xl text-sm transition-all ${
                              isChildActive
                                ? 'bg-blue-100 text-blue-700 font-medium'
                                : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
                            }`}
                          >
                            <ChildIcon className="w-4 h-4" />
                            {child.title}
                          </Link>
                        </li>
                      );
                    })}
                  </ul>
                )}
              </li>
            );
          })}
        </ul>
      </nav>

      {/* 底部信息 */}
      <div className="p-4 border-t border-gray-200 text-xs text-gray-400 text-center">
        Strapi 5 + Next.js
      </div>
    </div>
  );
}
